inline const Platform* SampleItem::platform() const {
    if (platform_) {
        return platform_.get();
    }
    if (!is_loaded("platform")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Platform>(ENTITY_NAME, id(), "platform");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Platform>(platformId());
}

